// Aplatit la sortie NocoDB v3 {id, fields:{}} au format plat du noeud
// Airtable historique : {...champs, id} -> aucune expression aval a changer.
return $input.all().map(i => ({ json: { ...(i.json.fields || {}), id: i.json.id } }));

// Carte « article à valider » (04/11/2026). Entrée : les brouillons `blog/` soumis
// (`pretAValider: true`), encore brouillons, et dont la carte n'est pas partie
// (`telegramNotifiedAt` vide) — filtrés par le Worker api.
// Sortie, par article : la pièce jointe HTML (binaire `data`, envoyée par sendDocument) et le
// corps de la carte (sendMessage, couverture en grand par l'aperçu de lien, boutons ✅/❌).
// ⛔ Ce workflow n'écrit JAMAIS `status` : la publication n'a lieu que sur le clic ✅
// (WF-TG-ROUTER → Worker api `blog/validation`).
const cfg = {};
for (const r of $('Aplatir — Lire Config').all()) { if (r.json.Cle) cfg[r.json.Cle] = r.json.Valeur; }
const token = cfg.TELEGRAM_BOT_TOKEN, chatId = cfg.TELEGRAM_CHAT_ID;
if (!token || !chatId) throw new Error('TELEGRAM_BOT_TOKEN / TELEGRAM_CHAT_ID absents de la Config NocoDB');

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const attr = (s) => esc(s).replace(/"/g, '&quot;');

// ── Entrée : la réponse de `POST api.maxmorrys.me/blog/validation {decision:'lister'}` ──
// (le Worker lit Firestore avec son compte de service ; le credential Google de n8n n'y a pas droit)
const rep = $input.first().json || {};
if (rep.ok !== true || !Array.isArray(rep.articles)) throw new Error('blog/validation lister : réponse inattendue — ' + JSON.stringify(rep).slice(0, 300));
const lignes = rep.articles;

// ── Markdown → HTML (sous-ensemble du blog : titres, listes, citations, tableaux, code, liens) ──
const inline = (t) => {
  const codes = [];
  let s = String(t).replace(/`([^`]+)`/g, (_, c) => { codes.push(c); return '\u0000' + (codes.length - 1) + '\u0000'; });
  s = esc(s);
  s = s.replace(/!\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g, (_, a, u) => '<img alt="' + a + '" src="' + u + '">');
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g, (_, a, u) => {
    const href = /^\//.test(u) ? 'https://maxmorrys.me' + u : u;
    return '<a href="' + href + '">' + a + '</a>';
  });
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>').replace(/__([^_]+)__/g, '<strong>$1</strong>');
  s = s.replace(/(^|[^*])\*([^*\s][^*]*)\*/g, '$1<em>$2</em>').replace(/(^|[\s(])_([^_\s][^_]*)_/g, '$1<em>$2</em>');
  return s.replace(/\u0000(\d+)\u0000/g, (_, i) => '<code>' + esc(codes[+i]) + '</code>');
};
const md2html = (md) => {
  const L = String(md || '').replace(/\r\n?/g, '\n').split('\n');
  const out = [];
  let i = 0;
  const isTableSep = (l) => /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)*\|?\s*$/.test(l);
  const cells = (l) => l.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());
  while (i < L.length) {
    const l = L[i];
    if (!l.trim()) { i++; continue; }
    if (/^```/.test(l)) {
      const buf = []; i++;
      while (i < L.length && !/^```/.test(L[i])) buf.push(L[i++]);
      i++; out.push('<pre><code>' + esc(buf.join('\n')) + '</code></pre>'); continue;
    }
    const h = l.match(/^(#{1,6})\s+(.*)$/);
    if (h) { const n = Math.min(6, h[1].length + 1); out.push('<h' + n + '>' + inline(h[2]) + '</h' + n + '>'); i++; continue; }
    if (/^\s*([-*_])(\s*\1){2,}\s*$/.test(l)) { out.push('<hr>'); i++; continue; }
    if (/^\s*\|/.test(l) && i + 1 < L.length && isTableSep(L[i + 1])) {
      const head = cells(l); i += 2;
      const body = [];
      while (i < L.length && /^\s*\|/.test(L[i])) body.push(cells(L[i++]));
      out.push('<div class="t"><table><thead><tr>' + head.map((c) => '<th>' + inline(c) + '</th>').join('') + '</tr></thead><tbody>' +
        body.map((r) => '<tr>' + r.map((c) => '<td>' + inline(c) + '</td>').join('') + '</tr>').join('') + '</tbody></table></div>');
      continue;
    }
    if (/^\s*>/.test(l)) {
      const buf = [];
      while (i < L.length && /^\s*>/.test(L[i])) buf.push(L[i++].replace(/^\s*>\s?/, ''));
      out.push('<blockquote>' + md2html(buf.join('\n')) + '</blockquote>'); continue;
    }
    const ul = /^\s*[-*+]\s+/, ol = /^\s*\d+[.)]\s+/;
    if (ul.test(l) || ol.test(l)) {
      const ordered = ol.test(l), re = ordered ? ol : ul, items = [];
      while (i < L.length && (re.test(L[i]) || (/^\s{2,}\S/.test(L[i]) && items.length))) {
        if (re.test(L[i])) items.push(L[i].replace(re, '')); else items[items.length - 1] += ' ' + L[i].trim();
        i++;
      }
      const tag = ordered ? 'ol' : 'ul';
      out.push('<' + tag + '>' + items.map((x) => '<li>' + inline(x) + '</li>').join('') + '</' + tag + '>'); continue;
    }
    const buf = [];
    while (i < L.length && L[i].trim() && !/^(#{1,6}\s|```|\s*>|\s*[-*+]\s+|\s*\d+[.)]\s+)/.test(L[i]) &&
      !(/^\s*\|/.test(L[i]) && i + 1 < L.length && isTableSep(L[i + 1]))) buf.push(L[i++].trim());
    out.push('<p>' + inline(buf.join(' ')) + '</p>');
  }
  return out.join('\n');
};
const texteBrut = (md) => String(md || '')
  .replace(/```[\s\S]*?```/g, ' ')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
  .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
  .replace(/^#{1,6}\s+/gm, '').replace(/^\s*>\s?/gm, '').replace(/^\s*[-*+]\s+/gm, '• ')
  .replace(/[*_`|]/g, '').replace(/[ \t]+/g, ' ');
const couper = (s, n) => {
  s = String(s || '').trim();
  if (s.length <= n) return s;
  const t = s.slice(0, n); const k = t.lastIndexOf(' ');
  return (k > n * 0.6 ? t.slice(0, k) : t).replace(/[\s,;:.]+$/, '') + '…';
};

const out = [];
for (const f of lignes) {
  // Le Worker ne renvoie que des brouillons soumis dont la carte n'est pas partie.
  const docId = String(f.id || '');
  if (!/^[A-Za-z0-9_-]+$/.test(docId)) continue;

  const contenu = String(f.content || '');
  const brut = texteBrut(contenu);
  const mots = brut.split(/\s+/).filter((w) => /[\p{L}\p{N}]/u.test(w)).length;
  // Introduction = ce qui précède le premier intertitre.
  const avantTitre = contenu.split(/\n(?=#{1,6}\s)/)[0];
  const intro = couper(texteBrut(avantTitre).replace(/\s*\n\s*/g, '\n').replace(/\n{2,}/g, '\n\n'), 600);
  const titreSeo = f.metaTitle || f.title || '';
  const test = f.test === true;
  const cover = /^https:\/\//.test(f.coverImage || '') ? f.coverImage : '';

  // ── Pièce jointe : l'article complet, lisible sur téléphone ──
  const html = '<!doctype html><html lang="fr"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">' +
    '<title>' + esc(f.title) + '</title><style>' +
    ':root{color-scheme:light dark}body{margin:0;font:17px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#fff;color:#1a1a1a}' +
    '@media (prefers-color-scheme:dark){body{background:#141414;color:#eaeaea}.meta,.badge{background:#222!important;border-color:#333!important}a{color:#8ab4ff}}' +
    'main{max-width:720px;margin:0 auto;padding:16px}img{max-width:100%;height:auto;border-radius:12px}' +
    'h1{font-size:1.6em;line-height:1.25;margin:.6em 0 .3em}h2{font-size:1.3em;margin:1.6em 0 .4em}h3{font-size:1.1em;margin:1.3em 0 .3em}' +
    '.meta{background:#f4f4f4;border:1px solid #e3e3e3;border-radius:12px;padding:12px 14px;font-size:.88em;line-height:1.5}' +
    '.badge{display:inline-block;background:#fff3cd;border:1px solid #f0d27a;border-radius:8px;padding:6px 10px;font-weight:600;margin:8px 0}' +
    'blockquote{margin:1em 0;padding:.2em 1em;border-left:4px solid #c9c9c9}pre{overflow:auto;padding:12px;border-radius:8px;background:rgba(127,127,127,.12)}' +
    'code{font-size:.9em}.t{overflow-x:auto}table{border-collapse:collapse;margin:1em 0;font-size:.92em}th,td{border:1px solid #ccc;padding:6px 8px;text-align:left;vertical-align:top}' +
    '</style></head><body><main>' +
    (test ? '<div class="badge">🧪 ARTICLE DE TEST — ne pas publier</div>' : '<div class="badge">Brouillon — à valider dans Telegram</div>') +
    (cover ? '<p><img src="' + attr(cover) + '" alt=""></p>' : '') +
    '<h1>' + esc(f.title) + '</h1>' +
    '<div class="meta"><b>Catégorie</b> : ' + esc(f.category || '—') + '<br><b>Mot-clé</b> : ' + esc(f.focusKeyword || '—') +
    '<br><b>Titre SEO</b> : ' + esc(titreSeo) + ' (' + titreSeo.length + ' car.)' +
    '<br><b>Méta-description</b> : ' + esc(f.metaDescription || '') + ' (' + String(f.metaDescription || '').length + ' car.)' +
    '<br><b>Adresse</b> : https://maxmorrys.me/blog/' + esc(f.slug) + '<br><b>Longueur</b> : ' + mots + ' mots · ' + esc(f.readTime || '?') + ' min' +
    (f.excerpt ? '<br><b>Chapô</b> : ' + esc(f.excerpt) : '') + '</div>' +
    md2html(contenu) + '</main></body></html>';
  const fichier = (String(f.slug || docId).replace(/[^a-z0-9-]/gi, '-').slice(0, 80) || 'article') + '.html';

  // ── La carte ──
  const tete = [
    (test ? '🧪 <b>TEST — article à valider</b> (rien ne sera publié)' : '📝 <b>Article à valider</b>'),
    '🏷 ' + esc(f.category || '—') + '  ·  🔑 ' + esc(f.focusKeyword || '—'),
    '📏 ' + mots + ' mots · ' + esc(f.readTime || '?') + ' min de lecture',
    '', '<b>' + esc(f.title) + '</b>',
    '<i>' + esc(f.metaDescription || f.excerpt || '') + '</i>', '', '',
  ].join('\n');
  const pied = '\n\n🔗 maxmorrys.me/blog/' + esc(f.slug) + '\n📎 Article complet : la pièce jointe juste au-dessus.' +
    '\n\n<i>Id ' + esc(docId) + '</i>';
  const max = 4096 - tete.length - pied.length - 2;
  let corps = intro;
  while (esc(corps).length > max) corps = corps.slice(0, -20) + '…';
  const reply_markup = { inline_keyboard: [[
    { text: '✅ Publier', callback_data: 'approve:article:' + docId },
    { text: '❌ Refuser', callback_data: 'reject:article:' + docId },
  ]] };
  const carte = {
    chat_id: chatId, text: tete + esc(corps) + pied, parse_mode: 'HTML', reply_markup,
    link_preview_options: cover ? { url: cover, prefer_large_media: true, show_above_text: true } : { is_disabled: true },
  };
  out.push({
    json: {
      docId, token, chatId, titre: f.title, carte,
      legende: (test ? '🧪 TEST — ' : '📎 ') + String(f.title || '').slice(0, 200) + ' — article complet (' + mots + ' mots)',
    },
    binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: fichier, fileExtension: 'html' } },
  });
}
return out;

// La carte part APRÈS la pièce jointe, en réponse à elle : les boutons restent le dernier
// message de la conversation. Entrée = réponses de sendDocument, dans l'ordre du Build
// (appariées par index). Si la pièce jointe a échoué, la carte part quand même et le dit.
// Sortie = uniquement les cartes envoyées (elles seules seront marquées notifiées : une
// carte en échec sera retentée au passage suivant). Aucune carte partie alors qu'il y en
// avait à envoyer ⇒ erreur (alerte WF-ERR), jamais un échec muet.
const http = this.helpers.httpRequest.bind(this);
const msgErr = (e) => String((e && e.response && e.response.body && e.response.body.description) || (e && e.description) || (e && e.message) || e).slice(0, 300);
const builds = $('Build — Carte article').all();
const reps = $input.all();
const out = [], erreurs = [];
for (let i = 0; i < builds.length; i++) {
  const b = builds[i].json;
  const r = (reps[i] && reps[i].json) || {};
  const docMsg = r.result && r.result.message_id;
  const carte = JSON.parse(JSON.stringify(b.carte));
  if (docMsg) carte.reply_parameters = { message_id: docMsg, allow_sending_without_reply: true };
  else carte.text = carte.text.replace('📎 Article complet : la pièce jointe juste au-dessus.',
    '⚠️ Pièce jointe non envoyée (' + String(r.error && (r.error.message || r.error) || r.description || 'erreur inconnue').slice(0, 120).replace(/[<>&]/g, ' ') + ') : relire le brouillon dans /admin/articles.');
  try {
    const res = await http({ method: 'POST', url: 'https://api.telegram.org/bot' + b.token + '/sendMessage', body: carte, json: true });
    const mid = res && res.result && res.result.message_id;
    if (!mid) throw new Error('sendMessage sans message_id');
    out.push({ json: { docId: b.docId, message_id: String(mid), document_message_id: docMsg ? String(docMsg) : '', notifiedAt: new Date().toISOString() } });
  } catch (e) {
    erreurs.push(b.docId + ' : ' + msgErr(e));
  }
}
if (erreurs.length) console.log('Cartes article en échec — ' + erreurs.join(' | '));
if (erreurs.length && !out.length) throw new Error('Aucune carte article envoyée — ' + erreurs.join(' | '));
return out;
